"""Built-in sample schemas and starter apps.

These used to live in the APEX page, but an APEX region source is capped at
32767 bytes and they pushed it over, which silently truncated the page's
JavaScript. They belong here anyway: the browser only needs a key such as
"react" or "sales", and the worker expands it when the request is run.
"""

from __future__ import annotations

